#!/bin/bash
set -e
VERSION=$(ruby -r ./version.rb -e 'puts $VERSION')

# Regenerate the source of truth the CI checks against.
cat > Sources/Core/Classes/SdkVersion.swift <<EOF
/// Generated by set_version.sh from version.rb — do not edit manually.
enum SdkVersion {
    static let current = "$VERSION"
}
EOF

# Fill in the tag/push commands so RELEASE.md's shell blocks are directly runnable.
sed -E -i '' \
  -e "s/(Add git tag \`)[^\`]+(\` to the merge commit)/\1$VERSION\2/" \
  -e "s/^([[:space:]]*git tag )[^ ]+/\1$VERSION/" \
  -e "s/^([[:space:]]*git push origin )[^ ]+/\1$VERSION/" \
  RELEASE.md

# Warn if the changelog's Unreleased section still has content pending a move.
if [ -n "$(awk '/^## Unreleased/{f=1;next} /^## /{f=0} f' CHANGELOG.md | tr -d '[:space:]')" ]; then
  echo "warning: CHANGELOG.md still has unreleased changes — move them to their own '## v$VERSION' section" >&2
fi

# Warn if there is no section for the new version yet.
if ! grep -qF "## v$VERSION" CHANGELOG.md; then
  echo "warning: CHANGELOG.md has no '## v$VERSION' section" >&2
fi
